//! Original fictional Zombiebox weapon meshes. +Y up; +Z forward; primary grip at origin.
use super::{GeometryTag, MaterialFlags, MeshBuffer, MeshBuilder, VertexMeta, WorldVertex};
use glam::Vec3;
#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub enum WeaponModel {
    Axe,
    Pistol,
    Shotgun,
    RocketLauncher,
    SniperRifle,
}
#[derive(Clone, Copy, Debug)]
pub struct WeaponNode { pub name: &'static str, pub parent: Option<&'static str>, pub translation: [f32; 3], pub group: &'static str, pub has_mesh: bool }
pub fn weapon_nodes(model: WeaponModel) -> &'static [WeaponNode] { match model {
    WeaponModel::Axe => AXE_NODES,
    WeaponModel::Pistol => PISTOL_NODES,
    WeaponModel::Shotgun => SHOTGUN_NODES,
    WeaponModel::RocketLauncher => ROCKET_LAUNCHER_NODES,
    WeaponModel::SniperRifle => SNIPER_RIFLE_NODES,
}}
pub fn weapon_mesh(model: WeaponModel, node: &str) -> Option<MeshBuffer> {
    let triangles = match (model,node) {
        (WeaponModel::Axe, "handle") => AXE_HANDLE,
        (WeaponModel::Axe, "head") => AXE_HEAD,
        (WeaponModel::Axe, "edge") => AXE_EDGE,
        (WeaponModel::Pistol, "frame") => PISTOL_FRAME,
        (WeaponModel::Pistol, "slide") => PISTOL_SLIDE,
        (WeaponModel::Pistol, "magazine") => PISTOL_MAGAZINE,
        (WeaponModel::Shotgun, "receiver") => SHOTGUN_RECEIVER,
        (WeaponModel::Shotgun, "stock") => SHOTGUN_STOCK,
        (WeaponModel::Shotgun, "barrel") => SHOTGUN_BARREL,
        (WeaponModel::Shotgun, "pump") => SHOTGUN_PUMP,
        (WeaponModel::RocketLauncher, "tube") => ROCKET_LAUNCHER_TUBE,
        (WeaponModel::RocketLauncher, "grip") => ROCKET_LAUNCHER_GRIP,
        (WeaponModel::RocketLauncher, "sight") => ROCKET_LAUNCHER_SIGHT,
        (WeaponModel::RocketLauncher, "shoulder_pad") => ROCKET_LAUNCHER_SHOULDER_PAD,
        (WeaponModel::SniperRifle, "receiver") => SNIPER_RIFLE_RECEIVER,
        (WeaponModel::SniperRifle, "stock") => SNIPER_RIFLE_STOCK,
        (WeaponModel::SniperRifle, "barrel") => SNIPER_RIFLE_BARREL,
        (WeaponModel::SniperRifle, "scope") => SNIPER_RIFLE_SCOPE,
        (WeaponModel::SniperRifle, "magazine") => SNIPER_RIFLE_MAGAZINE,
        (WeaponModel::SniperRifle, "bolt") => SNIPER_RIFLE_BOLT,
        _ => return None,
    };
    let meta = VertexMeta::DEFAULT.with_tag(GeometryTag::Actor).with_flags(MaterialFlags::ACTOR_MIN_LIGHT | MaterialFlags::CUTAWAY_EXEMPT);
    let mut b = MeshBuilder::new();
    for &(points,color) in triangles {
        let [a,c,d] = points.map(Vec3::from_array);
        b.push_triangle(a,c,d,WorldVertex::rgba8(color[0],color[1],color[2],255),meta);
    }
    Some(b.build())
}
type Triangle = ([[f32;3];3],[u8;3]);
